  scenery = {
    ["Aerie Peak"] = { type = "town", faction = "alliance", home = {  },
      { "Aerie Peak was carved into the mountain, home of the Wildhammer dwarves and their gryphons, with the wind blowing straight through it.", tags = { "!foe" } },
      { "Aerie Peak was a Wildhammer stronghold high on the mountain, and its gryphon riders saw everything that moved, me included.", tags = { "foe" } },
    },
    ["Ahn'Qiraj Temple"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Temple of Ahn'Qiraj went down into the dark, an insect empire's halls, and something very old was waiting at the bottom." },
    },
    ["Alterac Mountains"] = { type = "zone", faction = "neutral", home = {  },
      { "Snow and broken stone filled the Alterac Mountains, and the ruins of a fallen kingdom lay half buried in them. Ogres held the old city now, and the Syndicate held the roads.", tags = { "!night" } },
      { "The wind came down off the Alterac peaks at night, sharp as a blade. Somewhere among the ruins a fire was burning, and I had no wish to learn whose it was.", tags = { "night" } },
    },
    ["Arathi Highlands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Arathi Highlands rolled on under a wide sky, scattered with the ruins of Stromgarde and the standing stones of older times. Ogres, trolls and raiders had all taken their share of the land.", tags = { "!night" } },
      { "Night over Arathi was cold and wide, the circles of standing stones black against the stars. Whatever kingdoms had stood here, the wind had outlasted every one of them.", tags = { "night" } },
    },
    ["Ashenvale"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "Ashenvale was the old forest of my people, tall and quiet and full of moonwells. The Horde's axes had reached its edges, and I could not look at the stumps without anger.", tags = { "home", "!night" } },
      { "Under the moon, Ashenvale looked as it must always have looked, silver and still. Then I thought of the camps along its borders, and of how close the axes had come.", tags = { "home", "night" } },
      { "Ashenvale's trees were enormous and old, and the light through them fell blue and green. It was beautiful, and it was contested: every clearing had a sentinel watching it.", tags = { "ally" } },
      { "Ashenvale was dense, beautiful and hostile, and any tree could have hidden a sentinel. The Horde's lumber camps were few and far between, and the forest wanted them gone.", tags = { "foe" } },
    },
    ["Astranaar"] = { type = "town", faction = "alliance", home = {  },
      { "Astranaar stood on its island in the lake, its elven buildings pale among the trees and its sentinels always watching the shore.", tags = { "!foe" } },
      { "Astranaar sat on its island in the lake, ringed by sentinels who knew an enemy when they saw one.", tags = { "foe" } },
    },
    ["Auberdine"] = { type = "town", faction = "alliance", home = {  },
      { "Grey sea mist hung over the piers of Auberdine, and the boats came and went through it without hurry. I could see how a wait on this shore might stretch into days.", tags = { "!foe" } },
      { "The ships moored at Auberdine told me plainly whose shore this was. I admired the shelter of the piers, and did not expect a welcome beneath them.", tags = { "foe" } },
    },
    ["Azshara"] = { type = "zone", faction = "neutral", home = {  },
      { "Azshara was autumn everywhere, red and gold trees around the broken ruins of the old elves. It was beautiful in a way that felt like mourning.", tags = { "!night" } },
      { "At night Azshara's ruins stood pale among the trees, and the sea beyond them was very dark. The place still seemed to remember the queen it was named for.", tags = { "night" } },
    },
    ["Badlands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Badlands were dust and red rock under a sun with no mercy in it. The bones of great dragons lay half buried in the canyons, and nothing grew that did not have thorns.", tags = { "!night" } },
      { "The Badlands cooled quickly after dark, the canyons black and the stars hard and close. Somewhere a coyote called, and the echo came back from three directions at once.", tags = { "night" } },
    },
    ["Blackfathom Deeps"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Seawater had climbed the temple steps in Blackfathom Deeps and stayed there. Every sound carried through the drowned halls, so I listened before I moved." },
    },
    ["Blackrock Depths"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Blackrock Depths was a whole city under the mountain, the Dark Iron dwarves' kingdom of forges and lava. Its heat rose through the stone underfoot." },
    },
    ["Blackrock Spire"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Blackrock Spire rose inside the mountain, a fortress of orcs, ogres and dragonkin, with the black dragons' banners hanging over everything." },
    },
    ["Blackwing Lair"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Blackwing Lair stood at the top of Blackrock Spire, Nefarian's halls of dragons, experiments and cages." },
    },
    ["Blasted Lands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Blasted Lands were red, dead earth under a sickly sky, and in the south the Dark Portal stood silent. Everything here had been burned once and had never recovered.", tags = { "!night" } },
      { "At night the Blasted Lands seemed to glow, as if the ground itself remembered the fel. The Dark Portal loomed out of the dark, and it was hard not to feel watched.", tags = { "night" } },
